-- SERVYRA production data model (PostgreSQL)
create table if not exists users (id uuid primary key, email text unique not null, role text not null check (role in ('client','pro','admin')), verified boolean not null default false, created_at timestamptz not null default now());
create table if not exists professionals (id uuid primary key, user_id uuid references users(id), business_name text not null, category text not null, city text not null, active boolean not null default true, created_at timestamptz not null default now());
create table if not exists requests (id uuid primary key, user_id uuid references users(id), category text not null, description text not null, city text not null, budget_cents integer, status text not null default 'open', created_at timestamptz not null default now());
create table if not exists matches (id uuid primary key, request_id uuid references requests(id), professional_id uuid references professionals(id), score numeric not null, status text not null default 'offered', created_at timestamptz not null default now());
create table if not exists transactions (id uuid primary key, request_id uuid references requests(id), amount_cents integer not null, commission_cents integer not null, status text not null default 'pending', stripe_payment_id text, created_at timestamptz not null default now());
create table if not exists learning_events (id uuid primary key, category text, event_type text not null, score numeric not null default 1, consented boolean not null default false, created_at timestamptz not null default now());
create table if not exists ad_slots (id uuid primary key, name text not null, advertiser text, active boolean not null default false, price_cents integer, created_at timestamptz not null default now());